// Generated by vibelang from src/features/commands/metrics.ts; the migrate flow writes it again with each batch.
import { Metric } from "effect";
// Usage metrics for slash commands, exported over OTLP with the rest of the browser's telemetry (docs/observability.md).
// Labels carry how and which command the app offers, never what anyone typed. Each command's flow is counted with every
// dispatch (`smithers_flow_dispatches`, door `slash`).
/** Rows chosen from the menu, by `kind` (`commands` or `values`) and `how` (`accept`: Enter or a click; `complete`: Tab). */
export const choices = Metric.counter("smithers_slash_choices", {
    description: "Rows a person chose from the command menu",
    incremental: true,
});
/**
 * Command lines submitted, by `outcome` (`run`, `unknown`, `missing` or `invalid`) and, for a command the app offers,
 * `command`.
 */
export const submits = Metric.counter("smithers_slash_submits", {
    description: "Slash command lines submitted from the composer",
    incremental: true,
});
